def register(add):
    add("T105", title="表驱动测试与子测试", level="beginner", kind="test-package", runtime="desktop",
        files=["go.mod", "calc_test.go"], codeFile="calc_test.go", vkind="test-pass", expected="", run="go test ./...",
        concepts=["表驱动", "t.Run", "子测试", "测试"],
        summary="用表驱动测试与 t.Run 子测试覆盖多组用例，新增用例只需加一行数据。",
        objective="能编写表驱动测试并用 t.Run 组织子测试，理解子测试的独立性。",
        prereq=["T023 函数签名、多返回值与命名返回"],
        pitfalls=["循环变量捕获问题：子测试闭包引用循环变量，Go 1.22+ 已按轮次独立，但旧代码需显式拷贝。", "用例名重复：子测试名应唯一，否则会加 #01 后缀，难以定位。"],
        exercises=[{"prompt": "为 multiply 写表驱动测试，覆盖 0、负数、大数。", "hint": "表里每行 {name,a,b,want}。", "answer": "cases := []struct{...}{...}; for _, c := range cases { t.Run(c.name, func(t *testing.T){ ... }) }。"}],
        explain="表驱动测试把多组输入/期望放进一个切片，循环用 t.Run 建成子测试。好处：新增用例只加一行数据、子测试可单独运行（go test -run TestAdd/positive）、失败定位到具体子测试。示例为 Add 写了四组用例覆盖正数、含零、负数、正负抵消。这是最基础也最常用的 Go 测试写法。test-package 工程例子（go.mod + *_test.go），用官方 SDK 的 go test 运行；移动端不执行 go test，desktop only。")
    add("T106", title="断言与辅助函数、t.Helper", level="intermediate", kind="test-package", runtime="desktop",
        files=["go.mod", "assert_test.go"], codeFile="assert_test.go", vkind="test-pass", expected="", run="go test ./...",
        concepts=["断言辅助", "t.Helper", "失败定位", "测试"],
        summary="把重复断言抽成 helper 并用 t.Helper() 让失败行号指向调用处。",
        objective="能编写断言 helper 并用 t.Helper 保持失败定位在调用者而非 helper 内部。",
        prereq=["T105 表驱动测试与子测试"],
        pitfalls=["helper 里不调 t.Helper()：失败堆栈指向 helper 内部，定位困难。", "helper 里用 t.Fatal 之外的返回而忘记终止：可能继续执行导致误报。"],
        exercises=[{"prompt": "写一个 equalSlice helper 比较两个 []int 并调用 t.Helper。", "hint": "先比长度再逐元素比较。", "answer": "func equalSlice(t *testing.T, got, want []int){ t.Helper(); if len(got)!=len(want){t.Fatalf(...)}; for i:=range got{...} }。"}],
        explain="测试里常有重复的断言逻辑，抽成 helper 能减少样板。但 helper 内部失败若不调用 t.Helper()，报错行号会指向 helper 自身，而不是真正出错的调用点，调试成本高。t.Helper() 标记“这个函数是测试辅助”，使 t.Fatalf/Errorf 报告调用者的位置。示例提供 equalInt 与 assertTrue 两个 helper，并在 TestParseLen 中复用，验证失败定位正确。test-package，go test 运行，desktop only。")
